/**
 * ML FIX - a new blog post looks right without filling anything in
 *
 * Three things used to fail quietly when a post was published with the
 * Excerpt, Featured image and Category left alone, which is what happens
 * when somebody just writes and presses Publish:
 *
 *   1. No featured image, so the card had no picture at all while its
 *      neighbours did. The cards stayed the same height but everything
 *      inside them sat two hundred pixels out of line.
 *   2. The category fell to "Uncategorized", which is the absence of a
 *      category, and it was drawn as a pill as though it meant something.
 *   3. WordPress wrote the excerpt itself by cutting the first 55 words
 *      wherever they landed - and it counts words, so a Japanese post,
 *      having no spaces, was cut after about twenty characters.
 *
 * Each is handled below. All three are still overridden by anything typed
 * in the editor: set a featured image and the fallback steps aside, choose
 * a category and the pill shows it, write an excerpt and it is used as
 * written.
 */

/* ---------------------------------------------------------------------
 * 1. A card always has a picture
 * ------------------------------------------------------------------- */
add_filter( 'post_thumbnail_id', function ( $thumbnail_id, $post ) {
	if ( $thumbnail_id || is_admin() ) {
		return $thumbnail_id;
	}
	$post = get_post( $post );
	if ( ! $post || 'post' !== $post->post_type ) {
		return $thumbnail_id;
	}
	// Adam's own placeholder, already in the library. It reads as a frame
	// waiting for a picture rather than as a photograph nobody chose.
	return 18700;
}, 10, 2 );

/* ---------------------------------------------------------------------
 * 2. "Uncategorized" is not a category
 * ------------------------------------------------------------------- */
add_filter( 'get_the_terms', function ( $terms, $post_id, $taxonomy ) {
	if ( 'category' !== $taxonomy || is_wp_error( $terms ) || ! is_array( $terms ) ) {
		return $terms;
	}
	$hidden = array( 'uncategorized', 'uncategorised' );
	$kept   = array();
	foreach ( $terms as $term ) {
		$slug = urldecode( $term->slug );
		// the Japanese term is カテゴリーなし, whose slug is percent-encoded
		if ( in_array( $term->slug, $hidden, true ) || 'カテゴリーなし' === $term->name ) {
			continue;
		}
		$kept[] = $term;
	}
	// if that leaves nothing, hand back nothing rather than an empty pill
	return $kept;
}, 10, 3 );

/* ---------------------------------------------------------------------
 * 3. A readable summary, written from the post's own opening
 * ------------------------------------------------------------------- */
function ml_first_real_paragraph( $content ) {
	$content = preg_replace( '#<(script|style)\b.*?</\1>#is', '', $content );
	if ( ! preg_match_all( '#<p\b[^>]*>(.*?)</p>#is', $content, $m ) ) {
		// no paragraph markup: fall back to the whole thing as one block
		$m[1] = array( $content );
	}
	foreach ( $m[1] as $raw ) {
		$raw = trim( $raw );
		// a paragraph that is nothing but bold text is a heading someone
		// wrote as a paragraph, not a summary
		if ( preg_match( '#^<strong>.*</strong>$#is', $raw ) ) {
			continue;
		}
		$text = trim( html_entity_decode( wp_strip_all_tags( $raw ), ENT_QUOTES, 'UTF-8' ) );
		$text = preg_replace( '/\s+/u', ' ', $text );
		if ( '' === $text ) {
			continue;
		}
		// a byline, a "Takeaways" label, a table of contents heading
		if ( preg_match( '/^(by\s|takeaways?|key takeaways|contents|目次|まとめ)/iu', $text ) ) {
			continue;
		}
		if ( mb_strlen( $text, 'UTF-8' ) < 20 ) {
			continue;
		}
		return $text;
	}
	return '';
}

function ml_make_excerpt( $content ) {
	$text = ml_first_real_paragraph( $content );
	if ( '' === $text ) {
		return '';
	}
	// Japanese is counted in characters, not words: it has no spaces, so a
	// word count treats a whole post as one or two words.
	$japanese = (bool) preg_match( '/[\x{3040}-\x{30ff}\x{4e00}-\x{9fff}]/u', $text );
	$limit    = $japanese ? 95 : 210;
	$floor    = $japanese ? 24 : 44;
	$stops    = $japanese ? array( '。', '！', '？' ) : array( '. ', '! ', '? ' );

	if ( mb_strlen( $text, 'UTF-8' ) <= $limit ) {
		return $text;
	}
	$window = mb_substr( $text, 0, $limit + 1, 'UTF-8' );
	$cut    = -1;
	foreach ( $stops as $stop ) {
		$at = mb_strrpos( $window, $stop, 0, 'UTF-8' );
		if ( false !== $at && $at > $cut ) {
			$cut = $at;
		}
	}
	// a complete short sentence beats a long one cut off with an ellipsis
	if ( $cut >= $floor ) {
		return trim( mb_substr( $window, 0, $cut + 1, 'UTF-8' ) );
	}
	if ( $japanese ) {
		return rtrim( mb_substr( $window, 0, $limit, 'UTF-8' ) ) . '…';
	}
	$space = mb_strrpos( $window, ' ', 0, 'UTF-8' );
	if ( $space > 0 ) {
		return rtrim( mb_substr( $window, 0, $space, 'UTF-8' ), " ,;:" ) . '…';
	}
	return rtrim( mb_substr( $window, 0, $limit, 'UTF-8' ) ) . '…';
}

/**
 * Written into the post itself as it saves, rather than filtered on the way
 * out, for two reasons: the summary then shows in the Excerpt box where it
 * can be edited, and the card's dynamic tag reads the field directly and
 * never calls a display filter.
 */
add_filter( 'wp_insert_post_data', function ( $data, $postarr ) {
	if ( 'post' !== $data['post_type'] || 'auto-draft' === $data['post_status'] ) {
		return $data;
	}
	if ( ! empty( trim( $data['post_excerpt'] ) ) ) {
		return $data;   // Adam wrote one; leave it exactly as typed
	}
	$made = ml_make_excerpt( $data['post_content'] );
	if ( '' !== $made ) {
		$data['post_excerpt'] = $made;
	}
	return $data;
}, 10, 2 );
